#!/usr/bin/env python3
"""Emit vst/CoverArt.h from tools/ref_sprite_grid.py (same grid + tone
letters as the on-device ZDL cover, so the plugin UI shows our design)."""
from pathlib import Path

import sys
sys.path.insert(0, str(Path(__file__).resolve().parent))
from ref_sprite_grid import GRID  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent
out = ROOT / "vst" / "CoverArt.h"

rows, cols = len(GRID), len(GRID[0])
lines = [
    "/* Generated by tools/gen_vst_cover_art.py -- the plugin face: the same",
    " * 1-bpp chibi as the B1on ZDL screen cover (25x28 cells; tone letters",
    " * K/k/D/R/P/S).  Do not edit by hand. */",
    "#pragma once",
    "",
    f"static constexpr int kCoverCols = {cols};",
    f"static constexpr int kCoverRows = {rows};",
    "",
    "static const char* const kCoverGrid[kCoverRows] = {",
]
for r in GRID:
    lines.append(f'    "{r}",')
lines.append("};")
out.write_text("\n".join(lines) + "\n")
print(f"wrote {out}  ({cols}x{rows})")
